// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Phishable} from "../src/Phishable.sol";

contract InvMutTest is Test {
    Phishable c;

    function setUp() public { c = new Phishable(address(this)); }

    function testFuzz_property(address caller, address recipient) public {
        if (recipient == address(0)) recipient = address(1);
        uint256 fund = 1 ether;
        vm.deal(address(c), fund);

        bool ok;
        vm.prank(caller);
        try c.withdrawAll(recipient) {
            ok = true;
        } catch {
            ok = false;
        }

        if (caller == address(this)) {
            assertTrue(address(c).balance == 0);
        } else {
            assertTrue(address(c).balance == fund);
        }
    }
}
